  \\end{itemize}\n}\n\n% ═══════════════════════════════════════\n% ROW C (row16→bottom): Takeaways + References\n% ═══════════════════════════════════════\n\n% Col 1: Key Takeaways\n\\posterbox[tealcard, title={Key Takeaways for Developers}\n]{name=takeaways, column=1, between=row16 and bottom}{\n  \\fontsize{28}{38}\\selectfont\n  \\begin{enumerate}[itemsep=10pt]\n    \\item \\textbf{Compare within the same Chrome version.} Methodology and throttling differ across releases.\n    \\item \\textbf{Consult the latest run} (Chrome 146) for the most up-to-date framework standings.\n    \\item \\textbf{Know keyed vs non-keyed modes.} Recent odd Chrome runs benchmark keyed frameworks only.\n    \\item \\textbf{Understand the scoring change.} Weighted geometric mean (Chrome 118+) gives a more balanced score than arithmetic mean.\n    \\item \\textbf{60+ data points over 8 years} make this the most comprehensive JS framework performance tracker available.\n  \\end{enumerate}\n}\n\n% Col 2: References + Links\n\\posterbox[darkcard, title={Resources \\& Links}\n]{name=references, column=2, between=row16 and bottom}{\n  \\fontsize{28}{38}\\selectfont\n  \\begin{itemize}[itemsep=10pt]\n    \\item \\textbf{GitHub}: \\texttt{github.com/krausest/js-framework-benchmark}\n    \\item \\textbf{Results}: \\texttt{krausest.github.io/js-framework-benchmark}\n    \\item \\textbf{Latest Run}: Chrome 146 on macOS (2026)\n  \\end{itemize}\n  \\vspace{8pt}\n  \\darkcolorbox{primary!20}{%\n    {\\fontsize{26}{34}\\selectfont\\color{accent}\\textbf{Data source:} All figures from official benchmark result tables and project documentation. Each run uses Chrome stable with CPU throttling enabled.}\n  }\n  \\vspace{8pt}\n  \\begin{center}\n  {\\fontsize{22}{28}\\selectfont\\color{textdim}[QR Code → Paper \\& Code Repository]}\n  \\end{center}\n}\n\n\\end{tcbposter}\n\\end{document}\n", "numLines": 295, "startLine": 1, "totalLines": 295}}

