\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{shapes,arrows,positioning,backgrounds,calc}
\pagestyle{empty}

% ── Dark-Mode Developer Aesthetic ──
\definecolor{primary}{HTML}{3B82F6}       % electric blue
\definecolor{secondary}{HTML}{14B8A6}     % teal
\definecolor{accent}{HTML}{38BDF8}        % sky blue
\definecolor{warning}{HTML}{F59E0B}       % amber
\definecolor{posterbg}{HTML}{0B1121}      % deep navy background
\definecolor{cardbg}{HTML}{131B2E}        % card surface
\definecolor{cardbg2}{HTML}{162032}       % card surface alt
\definecolor{titlebg}{HTML}{1E293B}       % title card surface
\definecolor{statbg}{HTML}{172033}        % stat card surface
\definecolor{textlight}{HTML}{E2E8F0}     % primary text
\definecolor{textmuted}{HTML}{94A3B8}     % secondary text
\definecolor{textdim}{HTML}{64748B}       % dim text
\definecolor{warnbg}{HTML}{2D2110}        % amber-tinted card bg
\definecolor{warnborder}{HTML}{F59E0B}    % amber accent
\definecolor{bluebg}{HTML}{111D33}        % blue-tinted card bg
\definecolor{tealbg}{HTML}{0D1F1C}        % teal-tinted card bg
\definecolor{bluebar}{HTML}{1E3A5F}       % blue title bar bg
\definecolor{tealbar}{HTML}{134E4A}       % teal title bar bg
\definecolor{warnbar}{HTML}{3D2E0A}       % amber title bar bg

\pagecolor{posterbg}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=5pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=5pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles for dark mode ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=bluebar,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={primary!40},
    valign=top, drop shadow={opacity=0.25},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=tealbar,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.25},
  },
  warncard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=warnbg,
    borderline west={5pt}{0pt}{warning},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{warning},
    coltitle=warning, colbacktitle=warnbar,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={warning!40},
    valign=top, drop shadow={opacity=0.25},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{primary!60},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{primary!80},
    coltitle=primary!80, colbacktitle=titlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={primary!30},
    valign=top, drop shadow={opacity=0.25},
  },
}

% ── Utility commands ──
\newcommand{\darkcolorbox}[2]{%
  \colorbox{#1}{\parbox{0.92\linewidth}{\centering\vspace{4pt}#2\vspace{4pt}}}%
}
\newcommand{\statcallout}[2]{%
  \fcolorbox{primary!40}{statbg}{\parbox{0.85\linewidth}{%
    \centering\vspace{8pt}%
    {\fontsize{48}{58}\selectfont\bfseries\color{primary}#1}\\[4pt]
    {\fontsize{22}{28}\selectfont\color{textmuted}#2}\vspace{6pt}%
  }}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════
% TITLE BAR (rows top→row4, span=2)
% ═══════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg2, colframe=primary!30, colupper=textlight,
  arc=0pt, boxrule=0pt,
  left=32pt, right=32pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  borderline south={2pt}{0pt}{primary!50},
  drop shadow={opacity=0.35}
]{name=title, column=1, span=2, between=top and row4}{
  {\fontsize{64}{76}\selectfont\bfseries\color{white}JS Framework Benchmark}\\[10pt]
  {\fontsize{34}{42}\selectfont\color{primary!90}5 Years of Browser Performance Testing}\\[12pt]
  {\fontsize{24}{30}\selectfont\color{textmuted}Chrome 55 \quad$\rightarrow$\quad Chrome 146 \hspace{3em}$\cdot$\hspace{3em} 60+ Official Runs \hspace{3em}$\cdot$\hspace{3em} github.com/krausest/js-framework-benchmark}
}

% ═══════════════════════════════════════
% STAT BANNER (rows row4→row6, span=2)
% ═══════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=5pt, bottom=5pt,
  valign=center,
  borderline south={1.5pt}{0pt}{primary!25},
]{name=stats, column=1, span=2, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.228\linewidth}\centering
    {\fontsize{46}{56}\selectfont\bfseries\color{primary}60+}\\[3pt]
    {\fontsize{20}{26}\selectfont\color{textmuted}Total Official Runs}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.228\linewidth}\centering
    {\fontsize{46}{56}\selectfont\bfseries\color{secondary}55$\rightarrow$146}\\[3pt]
    {\fontsize{20}{26}\selectfont\color{textmuted}Chrome Versions}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.228\linewidth}\centering
    {\fontsize{46}{56}\selectfont\bfseries\color{warning}118}\\[3pt]
    {\fontsize{20}{26}\selectfont\color{textmuted}Methodology Overhaul}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.228\linewidth}\centering
    {\fontsize{46}{56}\selectfont\bfseries\color{accent}95\%+}\\[3pt]
    {\fontsize{20}{26}\selectfont\color{textmuted}macOS Platform}
  \end{minipage}
}

% ═══════════════════════════════════════
% ROW A (row6→row11): Overview + Timeline
% ═══════════════════════════════════════

% Col 1: What Is the JS Framework Benchmark?
\posterbox[bluecard, title={What Is the JS Framework Benchmark?}
]{name=overview, column=1, between=row6 and row11}{
  \fontsize{28}{38}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Most widely referenced \textbf{open-source benchmark} for comparing JavaScript web frameworks
    \item Measures \textbf{real-world DOM operations} inside a real Chrome browser with controlled CPU throttling
    \item Maintained by Stefan Krause, hosted on GitHub with community contributions
    \item Covers \textbf{dozens of frameworks} across keyed and non-keyed implementations
    \item Operations: create 1,000 rows, partial updates, row selection, swapping, removal, startup time
  \end{itemize}
  \vspace{3pt}
  \darkcolorbox{primary!20}{%
    {\fontsize{26}{34}\selectfont\color{accent}\textbf{Longest-running JS framework performance tracker} — 8 years of continuous measurement}
  }
}

% Col 2: Timeline Visualization (the centerpiece)
\posterbox[tealcard, title={Benchmark Timeline: Chrome 55 $\rightarrow$ 146}
]{name=timeline, column=2, between=row6 and row11}{
  \centering
  \begin{tikzpicture}[scale=1.0, every node/.style={transform shape}]
    % ── Timeline bar ──
    \fill[primary!20, rounded corners=3pt] (0,0) rectangle (13.2, 1.8);
    \fill[primary!40, rounded corners=3pt] (0,0) rectangle (13.2, 0.6);

    % Year markers
    \foreach \x/\y in {0/2017, 1.65/2018, 3.3/2019, 4.95/2020, 6.6/2021, 8.25/2022, 9.9/2023, 11.55/2024, 13.2/2025} {
      \draw[textmuted, line width=0.8pt] (\x, 0) -- (\x, -0.4) node[below, font=\fontsize{16}{20}\selectfont, text=textmuted] {\y};
    }

    % Chrome version labels
    \node[font=\fontsize{15}{18}\selectfont, text=primary!80] at (0.3, 1.35) {55};
