\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{shapes,arrows,positioning,backgrounds,calc,patterns}
\pagestyle{empty}

% ── Dark-Mode Developer Aesthetic ──
\definecolor{primary}{HTML}{3B82F6}       % electric blue
\definecolor{secondary}{HTML}{14B8A6}     % teal
\definecolor{accent}{HTML}{38BDF8}        % sky blue
\definecolor{warning}{HTML}{F59E0B}       % amber
\definecolor{posterbg}{HTML}{0B1121}      % deep navy background
\definecolor{cardbg}{HTML}{131B2E}        % card surface
\definecolor{cardbg2}{HTML}{162032}       % card surface alt
\definecolor{titlebg}{HTML}{1E293B}       % title card surface
\definecolor{textlight}{HTML}{E2E8F0}     % primary text
\definecolor{textmuted}{HTML}{94A3B8}     % secondary text
\definecolor{textdim}{HTML}{64748B}       % dim text
\definecolor{warnbg}{HTML}{2D2110}        % amber-tinted card bg
\definecolor{bluebg}{HTML}{111D33}        % blue-tinted card bg
\definecolor{tealbg}{HTML}{0D1F1C}        % teal-tinted card bg
\definecolor{bluebar}{HTML}{1E3A5F}       % blue title bar bg
\definecolor{tealbar}{HTML}{134E4A}       % teal title bar bg
\definecolor{warnbar}{HTML}{3D2E0A}       % amber title bar bg
\definecolor{yearearly}{HTML}{1E293B}     % early era bg
\definecolor{yearmid}{HTML}{1E2D3D}       % mid era bg
\definecolor{yearrecent}{HTML}{1D2535}    % recent era bg

\pagecolor{posterbg}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=18pt, itemsep=4pt, parsep=1pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=18pt, itemsep=4pt, parsep=1pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles for dark mode ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=bluebar,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={primary!40},
    valign=top, drop shadow={opacity=0.25},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=tealbar,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.25},
  },
  warncard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=warnbg,
    borderline west={5pt}{0pt}{warning},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{warning},
    coltitle=warning, colbacktitle=warnbar,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={warning!40},
    valign=top, drop shadow={opacity=0.25},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{primary!60},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{primary!80},
    coltitle=primary!80, colbacktitle=titlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={primary!30},
    valign=top, drop shadow={opacity=0.25},
  },
}

% ── Utility ──
\newcommand{\darkcolorbox}[2]{%
  \colorbox{#1}{\parbox{0.90\linewidth}{\centering\vspace{4pt}#2\vspace{4pt}}}%
}
\newcommand{\warnbox}[1]{%
  \colorbox{warning!18}{\parbox{0.90\linewidth}{\centering\vspace{4pt}{\fontsize{24}{32}\selectfont\color{warning}\textbf{#1}}\vspace{4pt}}}%
}
\newcommand{\bluebox}[1]{%
  \colorbox{primary!18}{\parbox{0.90\linewidth}{\centering\vspace{4pt}{\fontsize{24}{32}\selectfont\color{accent}\textbf{#1}}\vspace{4pt}}}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════
% TITLE BAR (top→row4, span=2)
% ═══════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg2, colframe=primary!30, colupper=textlight,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=12pt, bottom=10pt,
  halign=center, valign=center,
  borderline south={2.5pt}{0pt}{primary!60},
  drop shadow={opacity=0.35}
]{name=title, column=1, span=2, between=top and row4}{
  {\fontsize{68}{80}\selectfont\bfseries\color{white}JS Framework Benchmark}\\[10pt]
  {\fontsize{34}{42}\selectfont\color{primary!85}5 Years of Browser Performance Testing}\\[10pt]
  {\fontsize{22}{30}\selectfont\color{textmuted}Chrome 55 $\rightarrow$ Chrome 146 \hspace{2.5em}$\cdot$\hspace{2.5em} 60+ Official Runs \hspace{2.5em}$\cdot$\hspace{2.5em} Maintained by Stefan Krause \hspace{2.5em}$\cdot$\hspace{2.5em} github.com/krausest/js-framework-benchmark}
}

% ═══════════════════════════════════════
% STAT BANNER (row4→row6, span=2)
% ═══════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=4pt, bottom=4pt,
  valign=center,
  borderline south={1.5pt}{0pt}{primary!25},
]{name=stats, column=1, span=2, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.23\linewidth}\centering
    {\fontsize{52}{62}\selectfont\bfseries\color{primary}60+}\\[3pt]
    {\fontsize{22}{28}\selectfont\color{textmuted}Total Official Runs}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    {\fontsize{52}{62}\selectfont\bfseries\color{secondary}55$\rightarrow$146}\\[3pt]
    {\fontsize{22}{28}\selectfont\color{textmuted}Chrome Versions Covered}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    {\fontsize{52}{62}\selectfont\bfseries\color{warning}118}\\[3pt]
    {\fontsize{22}{28}\selectfont\color{textmuted}Scoring Method Changed}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    {\fontsize{52}{62}\selectfont\bfseries\color{accent}8 Years}\\[3pt]
    {\fontsize{22}{28}\selectfont\color{textmuted}Continuous Tracking}
  \end{minipage}
}

% ═══════════════════════════════════════
% ROW A (row6→row11): Overview + Timeline (centerpiece)
% ═══════════════════════════════════════

% Col 1: What Is It?
\posterbox[bluecard, title={What Is the JS Framework Benchmark?}
]{name=overview, column=1, between=row6 and row11}{
  \fontsize{28}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Most widely referenced} open-source benchmark for comparing JavaScript web frameworks
    \item Runs inside \textbf{real Chrome browser} with controlled CPU throttling
    \item Measures: create 1,000 rows, partial updates, row selection, swapping, removal, startup
    \item Covers \textbf{dozens of frameworks} in keyed \& non-keyed modes
  \end{itemize}
  \vspace{6pt}
  \bluebox{Longest-running JS framework performance tracker — 8 years of continuous measurement}
}

% Col 2: Timeline — THE CENTERPIECE
\posterbox[tealcard, title={Benchmark Timeline: Chrome 55 $\rightarrow$ 146}
]{name=timeline, column=2, between=row6 and row11}{
  \centering
  \begin{tikzpicture}[scale=1.0, every node/.style={transform shape}]
    % ── Era background bands ──
    \fill[yearearly!80, rounded corners=2pt] (0, -1.4) rectangle (3.3, 3.8);
    \fill[yearmid!60, rounded corners=2pt] (3.3, -1.4) rectangle (9.2, 3.8);
    \fill[yearrecent!50, rounded corners=2pt] (6.6, -1.4) rectangle (13.2, 3.8);

    % Era labels
    \node[font=\fontsize{15}{18}\selectfont, text=textdim] at (1.65, 3.4) {Early Era};
    \node[font=\fontsize{15}{18}\selectfont, text=textdim] at (6.25, 3.4) {Growth Era};
    \node[font=\fontsize{15}{18}\selectfont, text=textdim] at (9.9, 3.4) {Modern Era};

    % ── Main timeline bar ──
    \shade[left color=primary!30, right color=primary!50, rounded corners=3pt] (0,0.6) rectangle (13.2, 2.0);
    \fill[primary!50, rounded corners=3pt] (0,0.6) rectangle (13.2, 1.2);

    % Year markers on timeline
    \foreach \x/\y in {0/2017, 1.65/2018, 3.3/2019, 4.95/2020, 6.6/2021, 8.25/2022, 9.9/2023, 11.55/2024, 13.2/2025} {
      \draw[textmuted, line width=0.8pt] (\x, 0.6) -- (\x, 0.0) node[below, font=\fontsize{15}{18}\selectfont, text=textmuted] {\y};
    }

    % Chrome version callout boxes on timeline
    \node[fill=primary!30, rounded corners=2pt, inner sep=2pt, font=\fontsize{15}{18}\selectfont, text=white] at (0.4, 1.55) {Chrome 55};
    \node[fill=primary!30, rounded corners=2pt, inner sep=2pt, font=\fontsize{15}{18}\selectfont, text=white] at (3.6, 1.55) {Chrome 83};
    \node[fill=primary!30, rounded corners=2pt, inner sep=2pt, font=\fontsize{15}{18}\selectfont, text=white] at (6.9, 1.55) {Chrome 96};
    \node[fill=warning, rounded corners=2pt, inner sep=2pt, font=\fontsize{15}{18}\selectfont, text=black!80] at (9.2, 1.55) {Chrome 118};
    \node[fill=primary!50, rounded corners=2pt, inner sep=2pt, font=\fontsize{15}{18}\selectfont, text=white] at (12.5, 1.55) {146};

    % Run count badges
    \node[draw=textdim, fill=cardbg, rounded corners=2pt, inner sep=3pt, font=\fontsize{14}{18}\selectfont, text=textmuted] at (0.8, 2.6) {4 runs};
    \node[draw=textdim, fill=cardbg, rounded corners=2pt, inner sep=3pt, font=\fontsize{14}{18}\selectfont, text=textmuted] at (4.0, 2.6) {5 runs};
    \node[draw=textdim, fill=cardbg, rounded corners=2pt, inner sep=3pt, font=\fontsize{14}{18}\selectfont, text=textmuted] at (6.25, 2.6) {13 runs};
    \node[draw=textdim, fill=cardbg, rounded corners=2pt, inner sep=3pt, font=\fontsize{14}{18}\selectfont, text=textmuted] at (9.5, 2.6) {12 runs};
    \node[draw=textdim, fill=cardbg, rounded corners=2pt, inner sep=3pt, font=\fontsize{14}{18}\selectfont, text=textmuted] at (12.5, 2.6) {12 runs};

    % Milestone markers
    \fill[secondary] (0.4, 2.0) circle (3pt) node[above=4pt, font=\fontsize{14}{18}\selectfont, text=secondary, align=center] {First official\\run (2017)};
    \fill[secondary!70] (4.5, 2.0) circle (3pt) node[above=4pt, font=\fontsize{14}{18}\selectfont, text=secondary!70] {GitHub Pages};

    % ⚠ CAUTION ZONE — Chrome 118
    \draw[warning, line width=2.0pt, dashed] (9.2, -0.8) -- (9.2, 3.0);
    \fill[warning!30, rounded corners=3pt] (9.5, -0.3) rectangle (13.0, -1.1);
    \node[font=\fontsize{14}{18}\selectfont, text=warning, align=left] at (11.0, -0.7) {\textbf{Weighted Geometric Mean}};

    % Year era arrows
    \draw[textdim, line width=0.6pt, <->] (0, -0.8) -- (3.3, -0.8);
    \node[font=\fontsize{13}{16}\selectfont, text=textdim] at (1.65, -1.2) {stefankrause.net};

    \draw[textdim, line width=0.6pt, <->] (6.6, -0.8) -- (13.2, -0.8);
    \node[font=\fontsize{13}{16}\selectfont, text=textdim] at (9.9, -1.2) {GitHub Pages};

  \end{tikzpicture}
}

% ═══════════════════════════════════════
% ROW B (row11→row16): Methodology + Coverage
% ═══════════════════════════════════════

% Col 1: Methodology Milestones
\posterbox[warncard, title={Methodology Milestones \& Cross-Version Safety}
]{name=methodology, column=1, between=row11 and row16}{
  \fontsize{28}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Chrome 118}: \colorbox{warning!22}{\textbf{Weighted Geometric Mean}} replaced arithmetic mean as scoring method — single largest methodology shift
    \item \textbf{Chrome 118}: CPU throttling factors recalibrated for realistic load simulation
    \item \textbf{Chrome 118+}: Ongoing refinements to timing and driver instrumentation
    \item \textbf{Chrome 139+}: Odd Chrome versions benchmark keyed frameworks only
  \end{itemize}
  \vspace{6pt}
  \warnbox{Warning — Cross-version comparisons are unreliable. The benchmark and its driver are continuously evolving.}
}

% Col 2: Platform & Framework Coverage
\posterbox[bluecard, title={Platform \& Framework Coverage at a Glance}
]{name=coverage, column=2, between=row11 and row16}{
  \fontsize{26}{36}\selectfont
  \renewcommand{\arraystretch}{1.5}
  \centering
  \begin{tabular}{r|l|c}
    \rowcolor{primary!18} \textbf{Year} & \textbf{Chrome Versions} & \textbf{Runs} \\
    2017--19 & 55, 58, 62, 69 & 4 \\
    2020    & 83--87         & 5 \\
    2021    & 88--96         & 9 \\
    2022    & 97--108        & 13 \\
    2023    & 109--120       & 12 \\
    2024    & 121--131       & 12 \\
    2025    & 132--143       & 12 \\
    2026    & 144--146       & 3 (so far) \\
  \end{tabular}
  \vspace{6pt}
  \begin{itemize}[itemsep=6pt]
    \item \textbf{95\%+ macOS (OSX)} — only 2 out of 60+ runs on Windows (Chrome 104, 121)
    \item Keyed + non-keyed on even Chrome versions; keyed-only on odd (\texttt{>=}139)
  \end{itemize}
}

% ═══════════════════════════════════════
% ROW C (row16→bottom): Takeaways + Resources
% ═══════════════════════════════════════

% Col 1: Key Takeaways
\posterbox[tealcard, title={Key Takeaways for Developers}
]{name=takeaways, column=1, between=row16 and bottom}{
  \fontsize{28}{38}\selectfont
  \begin{enumerate}[itemsep=10pt]
    \item \textbf{Compare within the same Chrome version.} Methodology and throttling differ across releases — cross-version comparisons are unsafe.
    \item \textbf{Consult the latest run} (Chrome 146) for current framework standings — the most up-to-date snapshot.
    \item \textbf{Know keyed vs non-keyed modes.} Recent odd Chrome versions benchmark keyed frameworks only.
    \item \textbf{Understand the Chrome 118 shift.} Weighted geometric mean (Chrome 118+) gives a more balanced overall score than the previous arithmetic approach.
  \end{enumerate}
}

% Col 2: Resources + QR
\posterbox[darkcard, title={Resources \& Data Notes}
]{name=resources, column=2, between=row16 and bottom}{
  \fontsize{28}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Repository}: \texttt{github.com/krausest/js-framework-benchmark}
    \item \textbf{Results}: \texttt{krausest.github.io/js-framework-benchmark}
    \item \textbf{Latest}: Chrome 146 on macOS (May 2026)
  \end{itemize}
  \vspace{8pt}
  \bluebox{All data from official benchmark result tables. Each run uses Chrome stable with CPU throttling enabled.}
  \vspace{12pt}
  \begin{center}
  \begin{tikzpicture}
    \fill[cardbg2, rounded corners=4pt] (-2.5, -1.0) rectangle (2.5, 1.0);
    \draw[primary!40, line width=1pt, rounded corners=4pt] (-2.5, -1.0) rectangle (2.5, 1.0);
    \node[font=\fontsize{18}{24}\selectfont, text=textmuted] at (0, 0) {[ QR Code ]};
    \node[font=\fontsize{16}{20}\selectfont, text=textdim] at (0, -0.6) {Paper \& Code};
  \end{tikzpicture}
  \end{center}
}

