\posterbox[bluecard, title={What Is the JS Framework Benchmark?}
]{name=overview, column=1, between=row6 and row11}{
  \fontsize{28}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Most widely referenced} open-source benchmark for comparing JavaScript web frameworks
    \item Runs inside \textbf{real Chrome browser} with controlled CPU throttling
    \item Measures: create 1,000 rows, partial updates, row selection, swapping, removal, startup
    \item Covers \textbf{dozens of frameworks} in keyed \& non-keyed modes
  \end{itemize}
  \vspace{6pt}
  \bluebox{Longest-running JS framework performance tracker — 8 years of continuous measurement}
}

