% Col 1: Key Takeaways
\posterbox[tealcard, title={Key Takeaways for Developers}
]{name=takeaways, column=1, between=row16 and bottom}{
  \fontsize{28}{38}\selectfont
  \begin{enumerate}[itemsep=10pt]
    \item \textbf{Compare within the same Chrome version.} Methodology and throttling differ across releases — cross-version comparisons are unsafe.
    \item \textbf{Consult the latest run} (Chrome 146) for current framework standings — the most up-to-date snapshot.
    \item \textbf{Know keyed vs non-keyed modes.} Recent odd Chrome versions benchmark keyed frameworks only.
    \item \textbf{Understand the Chrome 118 shift.} Weighted geometric mean (Chrome 118+) gives a more balanced overall score than the previous arithmetic approach.
  \end{enumerate}
}

